               tmp34 = 1.0_wp/sqrt(tmp33)
               tmp35 = tmp34**(3)
               tmp36 = tmp28*tmp35
               tmp37 = tmp36*state%a(j)
               state%s14(i, j) = tmp37
               tmp38 = -tmp19
               tmp39 = state%s6(i)*tmp38
               tmp40 = -tmp22
               tmp41 = tmp40*state%s7(i)
               tmp42 = tmp39 + tmp41
               tmp43 = -tmp26
               tmp44 = tmp43*state%s8(i)
               tmp45 = tmp42 + tmp44
               tmp46 = tmp45*tmp35
               tmp47 = tmp46*state%a(i)
               state%s14(j, i) = tmp47
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp48 = state%k1(i) + state%k2(i)
         tmp49 = 3.141592653589793_wp*state%a(i)
         tmp50 = sqrt(tmp49)
         tmp51 = tmp48*tmp50
         tmp52 = (-0.5_wp)*tmp51
         state%s14(i, i) = tmp52
      end do

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine nonlocal_pcm_point_assemble

   !> Nonlocal PCM (point charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs nonlocal_pcm_point_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm_point
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[in] eps_inf  high-frequency permittivity of the solvent
   !> @param[in] lam  correlation length of the solvent polarization
   !> @param[in] eps_solute  relative permittivity inside the cavity
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_medium(state, eps, eps_inf, lam, eps_solute, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> High-frequency permittivity of the solvent
      real(wp), intent(in) :: eps_inf
      !> Correlation length of the solvent polarization
      real(wp), intent(in) :: lam
      !> Relative permittivity inside the cavity
      real(wp), intent(in) :: eps_solute
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp44, tmp66, tmp67, tmp68
      integer :: i, j

      if (state%matrix_free) then
         call nonlocal_pcm_point_mf_medium(state, eps, eps_inf, lam, eps_solute, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, &
                          "[nonlocal_pcm_point_medium] call nonlocal_pcm_point_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => lam)
      end associate

      state%op2%points => state%r
      state%op2%c1 => state%s5
      state%eps_solute = eps_solute
      state%eps_inf = eps_inf
      state%eps = eps
      state%op1%npt = 3*npt
      state%op1%npoint = npt
      state%op1%id = 1
      state%op1%points => state%r
      state%s9 = 1.0_wp/lam
      state%s10 = 1.0_wp/state%eps_inf
      state%s11 = state%s10*state%eps
      state%s12 = sqrt(state%s11)
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, &
                        tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, &
                        tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, &
                        tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, &
                        tmp43

            do i = 1, j - 1
               tmp1 = -state%s2(j)
               tmp2 = state%s2(i) + tmp1
               tmp3 = state%s6(j)*tmp2
               tmp4 = -state%s3(j)
               tmp5 = state%s3(i) + tmp4
               tmp6 = tmp5*state%s7(j)
               tmp7 = tmp3 + tmp6
               tmp8 = -state%s4(j)
               tmp9 = state%s4(i) + tmp8
               tmp10 = tmp9*state%s8(j)
               tmp11 = tmp7 + tmp10
               tmp12 = tmp2**(2)
               tmp13 = tmp5**(2)
               tmp14 = tmp12 + tmp13
               tmp15 = tmp9**(2)
               tmp16 = tmp14 + tmp15
               tmp17 = 1.0_wp/sqrt(tmp16)
               tmp18 = tmp17**(3)
               tmp19 = tmp11*tmp18
               tmp20 = sqrt(tmp16)
               tmp21 = state%s9*tmp20
               tmp22 = tmp21*state%s12
               tmp23 = -tmp22
               tmp24 = exp(tmp23)
               tmp25 = 1.0_wp + tmp22
               tmp26 = tmp24*tmp25
               tmp27 = -tmp26
               tmp28 = 1.0_wp + tmp27
               tmp29 = tmp19*tmp28
               tmp30 = tmp29*state%a(j)
               tmp31 = -tmp30
               state%s13(i, j) = tmp31
               tmp32 = -tmp2
               tmp33 = state%s6(i)*tmp32
               tmp34 = -tmp5
               tmp35 = tmp34*state%s7(i)
               tmp36 = tmp33 + tmp35
               tmp37 = -tmp9
               tmp38 = tmp37*state%s8(i)
               tmp39 = tmp36 + tmp38
               tmp40 = tmp39*tmp18
               tmp41 = tmp40*tmp28
               tmp42 = tmp41*state%a(i)
               tmp43 = -tmp42
               state%s13(j, i) = tmp43
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         state%s13(i, i) = 0.0_wp
      end do
      state%op1%c1 => state%s13
      state%op1%c2 => state%s14
      state%s15 = 1.0_wp/state%eps
      tmp44 = -state%s15
      state%s16 = state%s10 + tmp44
      state%s17 = state%eps_solute*state%s16
      state%op1%c3 = state%s17
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                        tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, &
                        tmp65

            do i = 1, j - 1
               tmp45 = -state%s2(j)
               tmp46 = state%s2(i) + tmp45
               tmp47 = tmp46**(2)
               tmp48 = -state%s3(j)
               tmp49 = state%s3(i) + tmp48
               tmp50 = tmp49**(2)
               tmp51 = tmp47 + tmp50
               tmp52 = -state%s4(j)
               tmp53 = state%s4(i) + tmp52
               tmp54 = tmp53**(2)
               tmp55 = tmp51 + tmp54
               tmp56 = sqrt(tmp55)
               tmp57 = state%s9*tmp56
               tmp58 = tmp57*state%s12
               tmp59 = -tmp58
               tmp60 = exp(tmp59)
               tmp61 = tmp60 - 1.0_wp
               tmp62 = 1.0_wp/sqrt(tmp55)
               tmp63 = tmp61*tmp62
               tmp64 = tmp63*state%a(j)
               state%s18(i, j) = tmp64
               tmp65 = tmp63*state%a(i)
               state%s18(j, i) = tmp65
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp66 = state%s9*state%a(i)
         tmp67 = tmp66*state%s12
         tmp68 = -tmp67
         state%s18(i, i) = tmp68
      end do
      state%op1%c4 => state%s18
      state%s19 = state%s10*state%eps_solute
      state%op1%c5 = state%s19
      state%op1%c6 => state%s5
      state%s20 = state%s15*state%eps_inf
      state%op1%c7 = state%s20
      call state%solver%setup(state%op1, error)
      if (allocated(error)) return
      state%s1 = 1.0_wp/state%eps_solute
      state%s21 = -state%s20
      state%s22 = 1.0_wp + state%s21
      state%s24 = -state%s17
      state%s26 = -state%s19
      state%s27 = 1.0_wp + state%s26
      state%s34 = 0.5_wp*state%s1
      state%s35 = (-6.283185307179586_wp)*state%s27
      state%s60 = lam**(-2)

      state%ready = 2
   end subroutine nonlocal_pcm_point_medium

   !> Nonlocal PCM (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs nonlocal_pcm_point_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm_point
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] u  interior trace of eps_solute times the reaction potential
   !> @param[out] q  interior normal trace of eps_solute times the reaction potential
   !> @param[out] w_ext  exterior auxiliary trace
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] grad_vn  partial derivative of the energy with respect to vn
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_solve(state, v, vn, energy, u, q, w_ext, grad_v, grad_vn, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Outward normal derivative of the solute potential at the surface points
      real(wp), contiguous, intent(in) :: vn(:)
      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Interior trace of eps_solute times the reaction potential
      real(wp), contiguous, intent(out) :: u(:)
      !> Interior normal trace of eps_solute times the reaction potential
      real(wp), contiguous, intent(out) :: q(:)
      !> Exterior auxiliary trace
      real(wp), contiguous, intent(out) :: w_ext(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Partial derivative of the energy with respect to vn
      real(wp), contiguous, intent(out) :: grad_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp10(:), tmp11(:), tmp14(:), tmp15(:), tmp16(:), tmp17(:), &
                               tmp18(:), tmp19(:), tmp20(:), tmp21(:), tmp22(:), tmp23(:), &
                               tmp25(:), tmp26(:), tmp27(:), tmp28(:), tmp29(:), tmp30(:), &
                               tmp31(:), tmp32(:), tmp33(:), tmp34(:), tmp35(:), tmp36(:), &
                               tmp37(:), tmp38(:), tmp39(:), tmp40(:), tmp41(:), tmp42(:), &
                               tmp43(:), tmp46(:), tmp47(:), tmp48(:), tmp49(:), tmp52(:), &
                               tmp53(:), tmp54(:), tmp55(:), tmp56(:), tmp57(:), tmp58(:), &
                               tmp59(:)
      real(wp), allocatable :: tmp8(:), tmp9(:), tmp12(:)
      real(wp) :: tmp13, tmp24, tmp44, tmp45, tmp50, tmp51, tmp60, tmp61

      if (state%matrix_free) then
         call nonlocal_pcm_point_mf_solve(state, v, vn, energy, u, q, w_ext, grad_v, grad_vn, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] call nonlocal_pcm_point_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] vn: wrong shape")
         return
      end if
      if (any(shape(u) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] u: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] q: wrong shape")
         return
      end if
      if (any(shape(w_ext) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] w_ext: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp20(npt), stat=stat)
      if (stat == 0) allocate (tmp21(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp33(npt), stat=stat)
      if (stat == 0) allocate (tmp34(npt), stat=stat)
      if (stat == 0) allocate (tmp35(npt), stat=stat)
      if (stat == 0) allocate (tmp36(npt), stat=stat)
      if (stat == 0) allocate (tmp37(npt), stat=stat)
      if (stat == 0) allocate (tmp38(npt), stat=stat)
      if (stat == 0) allocate (tmp39(npt), stat=stat)
      if (stat == 0) allocate (tmp40(npt), stat=stat)
      if (stat == 0) allocate (tmp41(npt), stat=stat)
      if (stat == 0) allocate (tmp42(npt), stat=stat)
      if (stat == 0) allocate (tmp43(npt), stat=stat)
      if (stat == 0) allocate (tmp46(npt), stat=stat)
      if (stat == 0) allocate (tmp47(npt), stat=stat)
      if (stat == 0) allocate (tmp48(npt), stat=stat)
      if (stat == 0) allocate (tmp49(npt), stat=stat)
      if (stat == 0) allocate (tmp52(npt), stat=stat)
      if (stat == 0) allocate (tmp53(npt), stat=stat)
      if (stat == 0) allocate (tmp54(npt), stat=stat)
      if (stat == 0) allocate (tmp55(npt), stat=stat)
      if (stat == 0) allocate (tmp56(npt), stat=stat)
      if (stat == 0) allocate (tmp57(npt), stat=stat)
      if (stat == 0) allocate (tmp58(npt), stat=stat)
      if (stat == 0) allocate (tmp59(npt), stat=stat)
      if (stat == 0) allocate (tmp8(3*npt), stat=stat)
      if (stat == 0) allocate (tmp9(3*npt), stat=stat)
      if (stat == 0) allocate (tmp12(3*npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[nonlocal_pcm_point_solve] allocation failed")
         return
      end if
      state%ready = 2

      state%op1%points => state%r
      state%op1%c1 => state%s13
      state%op1%c2 => state%s14
      state%op1%c4 => state%s18
      state%op1%c6 => state%s5
      state%op2%points => state%r
      state%op2%c1 => state%s5
      state%v = v
      state%vn = vn
      call gemv(state%s13, state%v, state%s23)
      call gemv(state%s18, state%vn, state%s25)
      call gemv(state%s14, state%v, tmp1)
      tmp2 = (-6.283185307179586_wp)*state%v
      state%s28 = tmp1 + tmp2
      tmp3 = state%s22*state%s23
      tmp4 = state%s24*state%s25
      tmp5 = tmp3 + tmp4
      tmp6 = state%s27*state%s28
      tmp7 = tmp5 + tmp6
      tmp8(1:npt) = tmp7
      tmp8(npt + 1:2*npt) = 0.0_wp
      tmp8(2*npt + 1:3*npt) = tmp6
      tmp9 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp8, tmp9, error)
      if (allocated(error)) return
      state%s29 = tmp9(1:npt)
      call state%solver%solve(state%op2, .false., state%s29, state%s30, error)
      if (allocated(error)) return
      tmp10 = state%a*state%s30
      state%s31 = dot(tmp10, state%v)
      state%s32 = tmp9(npt + 1:2*npt)
      state%s33 = tmp9(2*npt + 1:3*npt)
      state%s36 = state%s34*state%v
      tmp11 = state%s36*state%a
      call state%solver%solve(state%op2, .true., tmp11, state%s37, error)
      if (allocated(error)) return
      tmp12(1:npt) = state%s37
      tmp12(npt + 1:2*npt) = 0.0_wp
      tmp12(2*npt + 1:3*npt) = 0.0_wp
      call state%solver%solve(state%op1, .true., tmp12, state%s38, error)
      if (allocated(error)) return
      state%s39 = state%s38(2*npt + 1:3*npt)
      state%s40 = state%s38(1:npt)
      state%s41 = state%s39 + state%s40
      state%s42 = state%s27*state%s41
      state%s43 = state%s22*state%s40
      state%s44 = state%s24*state%s40
      state%s46 = state%vn + state%s32
      state%s48 = -state%s39
      state%s49 = -state%s40
      state%s50 = state%s21*state%s40
      state%s52 = state%s48 + state%s49
      tmp13 = state%s1*state%s31
      energy = 0.5_wp*tmp13
      u = state%s29
      q = state%s32
      tmp14 = state%s27*state%v
      w_ext = state%s33 + tmp14
      tmp15 = state%s34*tmp10
      tmp16 = state%s35*state%s41
      tmp17 = tmp15 + tmp16
      call gemv(state%s14, state%s42, tmp18, trans="t")
      tmp19 = tmp17 + tmp18
      call gemv(state%s13, state%s43, tmp20, trans="t")
      grad_v = tmp19 + tmp20
      call gemv(state%s18, state%s44, grad_vn, trans="t")
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         call gemv(state%s5, state%s30, tmp21)
         tmp22 = -tmp21
         tmp23 = state%s29 + tmp22
         tmp24 = dot(state%s37, tmp23)
         tmp25 = 6.283185307179586_wp*state%s29
         call gemv(state%s13, state%s29, tmp26)
         tmp27 = -tmp26
         tmp28 = tmp25 + tmp27
         call gemv(state%s14, state%s29, tmp29)
         tmp30 = -tmp29
         tmp31 = tmp28 + tmp30
         tmp32 = -tmp31
         tmp33 = tmp7 + tmp32
         call gemv(state%s18, state%s32, tmp34)
         tmp35 = state%s17*tmp34
         call gemv(state%s5, state%s32, tmp36)
         tmp37 = state%s19*tmp36
         tmp38 = tmp35 + tmp37
         tmp39 = -tmp38
         tmp40 = tmp33 + tmp39
         call gemv(state%s13, state%s33, tmp41)
         tmp42 = state%s21*tmp41
         tmp43 = tmp40 + tmp42
         tmp44 = dot(state%s40, tmp43)
         tmp45 = tmp24 + tmp44
         tmp46 = state%s38(npt + 1:2*npt)
         tmp47 = tmp25 + tmp29
         tmp48 = -tmp47
         tmp49 = tmp48 + tmp36
         tmp50 = dot(tmp46, tmp49)
         tmp51 = tmp45 + tmp50
         tmp52 = state%s26*tmp36
         tmp53 = tmp6 + tmp52
         tmp54 = 6.283185307179586_wp*state%s33
         call gemv(state%s14, state%s33, tmp55)
         tmp56 = -tmp55
         tmp57 = tmp54 + tmp56
         tmp58 = -tmp57
         tmp59 = tmp53 + tmp58
         tmp60 = dot(state%s39, tmp59)
         tmp61 = tmp51 + tmp60
         energy = energy + tmp61
      end if

      state%ready = 3
   end subroutine nonlocal_pcm_point_solve

   !> Nonlocal PCM (point charges): energy gradient with respect to the cavity inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs nonlocal_pcm_point_solve on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm_point
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_n  partial derivative of the energy with respect to n
   !> @param[out] grad_k1  partial derivative of the energy with respect to k1
   !> @param[out] grad_k2  partial derivative of the energy with respect to k2
   !> @param[out] grad_a  partial derivative of the energy with respect to a
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_weights(state, grad_r, grad_n, grad_k1, grad_k2, grad_a, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      real(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to n
      real(wp), contiguous, intent(out) :: grad_n(:, :)
      !> Partial derivative of the energy with respect to k1
      real(wp), contiguous, intent(out) :: grad_k1(:)
      !> Partial derivative of the energy with respect to k2
      real(wp), contiguous, intent(out) :: grad_k2(:)
      !> Partial derivative of the energy with respect to a
      real(wp), contiguous, intent(out) :: grad_a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp13(:), tmp19(:), tmp20(:), tmp21(:), tmp22(:), tmp26(:), &
                               tmp27(:), tmp28(:), tmp29(:), tmp30(:), tmp31(:), tmp32(:), &
                               tmp33(:), tmp34(:), tmp35(:), tmp260(:), tmp261(:), tmp262(:), &
