      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp11(3*npt), stat=stat)
      if (stat == 0) allocate (tmp12(3*npt), stat=stat)
      if (stat == 0) allocate (tmp20(3*npt), stat=stat)
      if (stat == 0) allocate (tmp21(3*npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[nonlocal_pcm_point_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s13
      state%op1%c2 => state%s14
      state%op1%c4 => state%s18
      state%op1%c6 => state%s5
      state%op2%points => state%r
      state%op2%c1 => state%s5
      call gemv(state%s13, dv, tmp1)
      tmp2 = state%s22*tmp1
      call gemv(state%s18, dvn, tmp3)
      tmp4 = state%s24*tmp3
      tmp5 = tmp2 + tmp4
      call gemv(state%s14, dv, tmp6)
      tmp7 = (-6.283185307179586_wp)*dv
      tmp8 = tmp6 + tmp7
      tmp9 = state%s27*tmp8
      tmp10 = tmp5 + tmp9
      tmp11(1:npt) = tmp10
      tmp11(npt + 1:2*npt) = 0.0_wp
      tmp11(2*npt + 1:3*npt) = tmp9
      tmp12 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp11, tmp12, error)
      if (allocated(error)) return
      tmp13 = tmp12(1:npt)
      tmp14 = 0.0_wp
      call state%solver%solve(state%op2, .false., tmp13, tmp14, error)
      if (allocated(error)) return
      tmp15 = state%a*tmp14
      tmp16 = state%s34*tmp15
      tmp17 = state%s34*dv
      tmp18 = tmp17*state%a
      tmp19 = 0.0_wp
      call state%solver%solve(state%op2, .true., tmp18, tmp19, error)
      if (allocated(error)) return
      tmp20(1:npt) = tmp19
      tmp20(npt + 1:2*npt) = 0.0_wp
      tmp20(2*npt + 1:3*npt) = 0.0_wp
      tmp21 = 0.0_wp
      call state%solver%solve(state%op1, .true., tmp20, tmp21, error)
      if (allocated(error)) return
      tmp22 = tmp21(2*npt + 1:3*npt)
      tmp23 = tmp21(1:npt)
      tmp24 = tmp22 + tmp23
      tmp25 = state%s35*tmp24
      tmp26 = tmp16 + tmp25
      tmp27 = state%s27*tmp24
      call gemv(state%s14, tmp27, tmp28, trans="t")
      tmp29 = tmp26 + tmp28
      tmp30 = state%s22*tmp23
      call gemv(state%s13, tmp30, tmp31, trans="t")
      hvp_v = tmp29 + tmp31
      tmp32 = state%s24*tmp23
      call gemv(state%s18, tmp32, hvp_vn, trans="t")
   end subroutine nonlocal_pcm_point_response_one

   !> Nonlocal PCM (point charges): energy derivatives with respect to the solvent parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs nonlocal_pcm_point_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm_point
   !> @param[out] grad_eps  partial derivative of the energy with respect to eps
   !> @param[out] grad_eps_inf  partial derivative of the energy with respect to eps_inf
   !> @param[out] grad_lam  partial derivative of the energy with respect to lam
   !> @param[out] grad_eps_solute  partial derivative of the energy with respect to eps_solute
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_point_param_weights(state, grad_eps, grad_eps_inf, grad_lam, &
                                               grad_eps_solute, error)
      !> State of nonlocal_pcm_point
      type(nonlocal_pcm_point_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to eps
      real(wp), intent(out) :: grad_eps
      !> Partial derivative of the energy with respect to eps_inf
      real(wp), intent(out) :: grad_eps_inf
      !> Partial derivative of the energy with respect to lam
      real(wp), intent(out) :: grad_lam
      !> Partial derivative of the energy with respect to eps_solute
      real(wp), intent(out) :: grad_eps_solute
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp4(:), tmp10(:), tmp18(:), tmp19(:), tmp22(:), tmp23(:), &
                               tmp24(:), tmp25(:), tmp26(:), tmp27(:), tmp30(:), tmp31(:), &
