      real(wp) :: tmp1, tmp2, tmp3, tmp5, tmp6, tmp7, tmp8, tmp9, tmp11, tmp12, tmp13, tmp14, &
                  tmp15, tmp16, tmp17, tmp20, tmp21, tmp28, tmp29, tmp99, tmp100, tmp101, tmp102, &
