            tmp36 = state%s4(j)
            tmp37 = state%a(j)
            tmp38 = state%s46(j)
            tmp39 = state%s6(j)
            tmp40 = state%s7(j)
            tmp41 = state%s8(j)
            tmp42 = state%v(j)
            tmp43 = state%s33(j)
            tmp44 = state%s29(j)
            tmp45 = -tmp34
            tmp48 = -tmp35
            tmp52 = -tmp36
            !$omp simd
