                  real(wp) :: tmp46, tmp47, tmp49, tmp50, tmp51, tmp53, tmp54, tmp55, tmp56, &
                              tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, &
                              tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, tmp74, &
                              tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, &
                              tmp84, tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, tmp92, &
                              tmp93, tmp94, tmp95, tmp96, tmp97, tmp98

                  tmp46 = state%s2(i) + tmp45
                  tmp47 = tmp46**(2)
                  tmp49 = state%s3(i) + tmp48
                  tmp50 = tmp49**(2)
                  tmp51 = tmp47 + tmp50
                  tmp53 = state%s4(i) + tmp52
                  tmp54 = tmp53**(2)
                  tmp55 = tmp51 + tmp54
                  tmp56 = sqrt(tmp55)
                  tmp57 = state%s9*tmp56
                  tmp58 = tmp57*state%s12
                  tmp59 = -tmp58
                  tmp60 = exp(tmp59)
                  tmp61 = tmp60*state%s9
                  tmp62 = tmp61*tmp37
                  tmp63 = tmp62*tmp38
                  tmp64 = -tmp63
                  tmp18(i) = tmp18(i) + tmp64
                  tmp65 = tmp39*tmp46
                  tmp66 = tmp49*tmp40
                  tmp67 = tmp65 + tmp66
                  tmp68 = tmp53*tmp41
                  tmp69 = tmp67 + tmp68
                  tmp70 = tmp60*tmp69
                  tmp71 = 1.0_wp/sqrt(tmp55)
                  tmp72 = tmp71**(3)
                  tmp73 = tmp70*tmp72
                  tmp74 = tmp73*tmp37
                  tmp75 = 1.0_wp + tmp58
                  tmp76 = tmp74*tmp75
                  tmp77 = -tmp76
                  tmp78 = tmp74 + tmp77
                  tmp79 = tmp78*state%s9
                  tmp80 = tmp79*tmp42
                  tmp81 = tmp80*tmp56
                  tmp23(i) = tmp23(i) + tmp81
                  tmp82 = tmp43*tmp78
                  tmp83 = tmp82*state%s9
                  tmp84 = tmp83*tmp56
                  tmp24(i) = tmp24(i) + tmp84
                  tmp85 = tmp79*tmp44
                  tmp86 = tmp85*tmp56
                  tmp25(i) = tmp25(i) + tmp86
                  tmp87 = tmp60*tmp37
                  tmp88 = tmp87*tmp38
                  tmp89 = tmp88*state%s12
                  tmp90 = -tmp89
                  tmp26(i) = tmp26(i) + tmp90
                  tmp91 = tmp78*tmp42
                  tmp92 = tmp91*tmp56
                  tmp93 = tmp92*state%s12
                  tmp31(i) = tmp31(i) + tmp93
                  tmp94 = tmp82*tmp56
                  tmp95 = tmp94*state%s12
                  tmp32(i) = tmp32(i) + tmp95
                  tmp96 = tmp78*tmp44
                  tmp97 = tmp96*tmp56
                  tmp98 = tmp97*state%s12
                  tmp33(i) = tmp33(i) + tmp98
               end block
            end do
            !$omp simd
            do i = j + 1, npt
               block
                  real(wp) :: tmp46, tmp47, tmp49, tmp50, tmp51, tmp53, tmp54, tmp55, tmp56, &
                              tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, &
                              tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, tmp74, &
                              tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, &
                              tmp84, tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, tmp92, &
                              tmp93, tmp94, tmp95, tmp96, tmp97, tmp98

                  tmp46 = state%s2(i) + tmp45
                  tmp47 = tmp46**(2)
                  tmp49 = state%s3(i) + tmp48
                  tmp50 = tmp49**(2)
                  tmp51 = tmp47 + tmp50
                  tmp53 = state%s4(i) + tmp52
                  tmp54 = tmp53**(2)
                  tmp55 = tmp51 + tmp54
                  tmp56 = sqrt(tmp55)
                  tmp57 = state%s9*tmp56
                  tmp58 = tmp57*state%s12
                  tmp59 = -tmp58
                  tmp60 = exp(tmp59)
                  tmp61 = tmp60*state%s9
                  tmp62 = tmp61*tmp37
                  tmp63 = tmp62*tmp38
                  tmp64 = -tmp63
                  tmp18(i) = tmp18(i) + tmp64
                  tmp65 = tmp39*tmp46
                  tmp66 = tmp49*tmp40
                  tmp67 = tmp65 + tmp66
                  tmp68 = tmp53*tmp41
                  tmp69 = tmp67 + tmp68
                  tmp70 = tmp60*tmp69
                  tmp71 = 1.0_wp/sqrt(tmp55)
                  tmp72 = tmp71**(3)
                  tmp73 = tmp70*tmp72
                  tmp74 = tmp73*tmp37
                  tmp75 = 1.0_wp + tmp58
                  tmp76 = tmp74*tmp75
                  tmp77 = -tmp76
                  tmp78 = tmp74 + tmp77
                  tmp79 = tmp78*state%s9
                  tmp80 = tmp79*tmp42
                  tmp81 = tmp80*tmp56
                  tmp23(i) = tmp23(i) + tmp81
                  tmp82 = tmp43*tmp78
                  tmp83 = tmp82*state%s9
                  tmp84 = tmp83*tmp56
                  tmp24(i) = tmp24(i) + tmp84
                  tmp85 = tmp79*tmp44
                  tmp86 = tmp85*tmp56
                  tmp25(i) = tmp25(i) + tmp86
                  tmp87 = tmp60*tmp37
                  tmp88 = tmp87*tmp38
                  tmp89 = tmp88*state%s12
                  tmp90 = -tmp89
                  tmp26(i) = tmp26(i) + tmp90
