      tmp99 = dot(state%s44, tmp18)
      tmp100 = dot(state%s43, tmp23)
      tmp101 = dot(state%s50, tmp24)
      tmp102 = tmp100 + tmp101
      tmp103 = dot(state%s40, tmp25)
      tmp104 = tmp102 + tmp103
      tmp105 = tmp99 + tmp104
      tmp106 = state%s10*tmp105
      tmp107 = 1.0_wp/sqrt(state%s11)
      tmp108 = tmp106*tmp107
