      tmp112 = dot(state%s41, state%s28)
      tmp113 = -tmp112
      call gemv(state%s5, state%s32, tmp114)
      tmp115 = dot(state%s52, tmp114)
      tmp116 = tmp113 + tmp115
      tmp117 = state%eps_solute*tmp116
      tmp118 = tmp117 + tmp13
      tmp119 = tmp105*state%eps
