            tmp6 = tmp2*x
            tmp1 = tmp6
            !$omp parallel &
            !$omp& private(i, j) &
            !$omp& shared(self, tmp1, x) &
            !$omp& default(private)
            block
               real(wp) :: tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, tmp16, tmp20, tmp7

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp8 = x(j)
                  tmp9 = self%r(1, j)
                  tmp10 = self%r(2, j)
                  tmp11 = self%r(3, j)
                  tmp12 = self%a(j)
                  tmp13 = -tmp9
                  tmp16 = -tmp10
                  tmp20 = -tmp11
                  tmp7 = 0.0_wp
                  !$omp simd &
                  !$omp& reduction(+: tmp7)
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp14, tmp15, tmp17, tmp18, tmp19, tmp21, tmp22, tmp23, tmp24, &
                                    tmp25, tmp26

                        tmp14 = self%r(1, i) + tmp13
                        tmp15 = tmp14**(2)
                        tmp17 = self%r(2, i) + tmp16
                        tmp18 = tmp17**(2)
                        tmp19 = tmp15 + tmp18
                        tmp21 = self%r(3, i) + tmp20
                        tmp22 = tmp21**(2)
                        tmp23 = tmp19 + tmp22
                        tmp24 = 1.0_wp/sqrt(tmp23)
                        tmp25 = x(i)*tmp24
                        tmp26 = tmp25*tmp12
                        tmp7 = tmp7 + tmp26
                     end block
                  end do
                  !$omp simd &
                  !$omp& reduction(+: tmp7)
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp14, tmp15, tmp17, tmp18, tmp19, tmp21, tmp22, tmp23, tmp24, &
                                    tmp25, tmp26

                        tmp14 = self%r(1, i) + tmp13
                        tmp15 = tmp14**(2)
                        tmp17 = self%r(2, i) + tmp16
                        tmp18 = tmp17**(2)
                        tmp19 = tmp15 + tmp18
                        tmp21 = self%r(3, i) + tmp20
                        tmp22 = tmp21**(2)
                        tmp23 = tmp19 + tmp22
                        tmp24 = 1.0_wp/sqrt(tmp23)
                        tmp25 = x(i)*tmp24
                        tmp26 = tmp25*tmp12
                        tmp7 = tmp7 + tmp26
                     end block
                  end do
                  tmp1(j) = tmp1(j) + tmp7
               end do
               !$omp end do
            end block
            !$omp end parallel
            y = tmp1
         end block
      else
         block
            real(wp), allocatable :: tmp1(:), tmp2(:), tmp6(:)
            real(wp) :: tmp3, tmp4, tmp5
            integer :: i, j

            allocate (tmp1(self%npt))
            allocate (tmp2(self%npt))
            allocate (tmp6(self%npt))
            do i = 1, self%npt
               tmp3 = 3.141592653589793_wp*self%a(i)
               tmp4 = sqrt(tmp3)
               tmp5 = 2.0_wp*tmp4
               tmp2(i) = tmp5
            end do
            tmp6 = tmp2*x
            tmp1 = tmp6
            !$omp parallel &
            !$omp& private(i, j) &
            !$omp& shared(self, x) &
            !$omp& reduction(+: tmp1) &
            !$omp& default(private)
            block
               real(wp) :: tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp15, tmp19

               !$omp do schedule(static)
               do j = 1, self%npt
                  tmp7 = x(j)
                  tmp8 = self%r(1, j)
                  tmp9 = self%r(2, j)
                  tmp10 = self%r(3, j)
                  tmp11 = self%a(j)
                  tmp12 = -tmp8
                  tmp15 = -tmp9
                  tmp19 = -tmp10
                  !$omp simd
                  do i = 1, j - 1
                     block
                        real(wp) :: tmp13, tmp14, tmp16, tmp17, tmp18, tmp20, tmp21, tmp22, tmp23, &
                                    tmp24, tmp25

                        tmp13 = self%r(1, i) + tmp12
                        tmp14 = tmp13**(2)
                        tmp16 = self%r(2, i) + tmp15
                        tmp17 = tmp16**(2)
                        tmp18 = tmp14 + tmp17
                        tmp20 = self%r(3, i) + tmp19
                        tmp21 = tmp20**(2)
                        tmp22 = tmp18 + tmp21
                        tmp23 = 1.0_wp/sqrt(tmp22)
                        tmp24 = tmp7*tmp23
                        tmp25 = tmp24*tmp11
                        tmp1(i) = tmp1(i) + tmp25
                     end block
                  end do
                  !$omp simd
                  do i = j + 1, self%npt
                     block
                        real(wp) :: tmp13, tmp14, tmp16, tmp17, tmp18, tmp20, tmp21, tmp22, tmp23, &
                                    tmp24, tmp25

                        tmp13 = self%r(1, i) + tmp12
                        tmp14 = tmp13**(2)
                        tmp16 = self%r(2, i) + tmp15
                        tmp17 = tmp16**(2)
                        tmp18 = tmp14 + tmp17
                        tmp20 = self%r(3, i) + tmp19
                        tmp21 = tmp20**(2)
                        tmp22 = tmp18 + tmp21
                        tmp23 = 1.0_wp/sqrt(tmp22)
                        tmp24 = tmp7*tmp23
                        tmp25 = tmp24*tmp11
                        tmp1(i) = tmp1(i) + tmp25
                     end block
                  end do
               end do
               !$omp end do
            end block
            !$omp end parallel
            y = tmp1
         end block
      end if
   end subroutine nonlocal_pcm_point_op4_apply

   !> Form operator 4 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine nonlocal_pcm_point_op4_assemble_block(self, idx, a, error)
      !> Operator
      class(nonlocal_pcm_point_op4), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp2(:)
      real(wp), allocatable :: tmp1(:, :)
      real(wp) :: tmp17, tmp18, tmp19
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[nonlocal_pcm_point_op4_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[nonlocal_pcm_point_op4_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%a(idx)
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(a, nb, tmp1, tmp2)
      do j = 1, nb
         block
            real(wp) :: tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, &
                        tmp14, tmp15, tmp16

            do i = 1, j - 1
               tmp3 = -tmp1(1, j)
               tmp4 = tmp1(1, i) + tmp3
               tmp5 = tmp4**(2)
               tmp6 = -tmp1(2, j)
               tmp7 = tmp1(2, i) + tmp6
               tmp8 = tmp7**(2)
               tmp9 = tmp5 + tmp8
               tmp10 = -tmp1(3, j)
               tmp11 = tmp1(3, i) + tmp10
               tmp12 = tmp11**(2)
               tmp13 = tmp9 + tmp12
               tmp14 = 1.0_wp/sqrt(tmp13)
               tmp15 = tmp14*tmp2(j)
               a(i, j) = tmp15
               tmp16 = tmp14*tmp2(i)
               a(j, i) = tmp16
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, nb
         tmp17 = 3.141592653589793_wp*tmp2(i)
         tmp18 = sqrt(tmp17)
         tmp19 = 2.0_wp*tmp18
         a(i, i) = tmp19
      end do
   end subroutine nonlocal_pcm_point_op4_assemble_block

end module pcmgen_point_nonlocal
